import sys
from collections import Counter

MOD = 10**9 + 7

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    t = int(input[idx])
    idx += 1
    results = []
    while t > 0:
        n = int(input[idx])
        idx += 1
        a = list(map(int, input[idx:idx+n]))
        idx += n
        b = list(map(int, input[idx:idx+n]))
        idx += n
        d = list(map(int, input[idx:idx+n]))
        idx += n

        used = [False] * (n + 1)
        for x in d:
            if x != 0:
                used[x] = True

        free_a = [x for x in a if not used[x]]
        free_b = [x for x in b if not used[x]]

        count = 1
        for i in range(n):
            if d[i] == 0:
                if free_a and free_b and free_a[-1] == free_b[-1]:
                    count = (count * 1) % MOD
                elif free_a and free_b:
                    count = (count * 2) % MOD
                elif free_a or free_b:
                    count = (count * 1) % MOD
                else:
                    count = 0
                    break
                if free_a and free_a[-1] == d[i]:
                    free_a.pop()
                elif free_b and free_b[-1] == d[i]:
                    free_b.pop()
                elif free_a:
                    free_a.pop()
                elif free_b:
                    free_b.pop()

        results.append(count)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
